from collections import defaultdict

def solve(data):
    n = data['n']
    edges = data['edges']

    # Check if there is a cycle in the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    visited = set()
    stack = []
    has_cycle = False

    def dfs(node):
        nonlocal has_cycle
        if node in visited:
            has_cycle = True
            return
        visited.add(node)
        stack.append(node)
        for neighbor in graph[node]:
            dfs(neighbor)
        if has_cycle:
            return
        stack.pop()

    for i in range(n):
        if i not in visited:
            dfs(i)

    if has_cycle:
        return []

    # Construct the topological order
    topological_order = []
    while stack:
        topological_order.append(stack.pop())

    return topological_order

